/**
 * BrollLayer.tsx — Remotion B-roll rendering component.
 *
 * Receives a manifest array as a prop (generated by the pipeline).
 * Handles crossfades, zoom, and graceful fallback for missing assets.
 */

import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  staticFile,
  Video,
  Sequence,
} from "remotion";
import { EASE_IN, EASE_OUT } from "../../design/motion";
import { tween } from "../../design/motion";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface BrollManifestEntry {
  phraseIndex: number;
  file: string;
  from: number;
  to: number;
  zoomRange: [number, number];
}

export interface BrollLayerProps {
  /** B-roll manifest entries */
  manifest: BrollManifestEntry[];
  /** Crossfade duration in ms */
  crossfadeMs?: number;
  /** Show debug overlay */
  debug?: boolean;
  /** Fallback: children rendered behind B-roll */
  children?: React.ReactNode;
}

// ─── Component ────────────────────────────────────────────────────────────────

export const BrollLayer: React.FC<BrollLayerProps> = ({
  manifest,
  crossfadeMs = 600,
  debug = false,
  children,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const currentMs = (frame / fps) * 1000;

  // Find active clip for current frame
  const activeClip = useMemo(() => {
    return manifest.find(
      (entry) => frame >= entry.from && frame <= entry.to
    ) ?? null;
  }, [manifest, frame]);

  if (!activeClip) {
    if (debug) {
      return (
        <AbsoluteFill style={{ zIndex: 3, pointerEvents: "none" }}>
          <div
            style={{
              position: "absolute",
              top: 10,
              left: 10,
              color: "white",
              background: "rgba(0,0,0,0.7)",
              padding: "4px 8px",
              fontSize: 12,
              fontFamily: "monospace",
            }}
          >
            No B-roll at frame {frame}
          </div>
        </AbsoluteFill>
      );
    }
    return null;
  }

  // Compute crossfade opacity
  const clipStartMs = (activeClip.from / fps) * 1000;
  const clipEndMs = (activeClip.to / fps) * 1000;
  const clipDurationMs = clipEndMs - clipStartMs;
  const clipElapsedMs = currentMs - clipStartMs;

  let opacity = 1;
  if (clipElapsedMs < crossfadeMs) {
    opacity = tween(clipElapsedMs / crossfadeMs, EASE_OUT);
  } else if (clipElapsedMs > clipDurationMs - crossfadeMs) {
    opacity =
      1 -
      tween(
        (clipElapsedMs - (clipDurationMs - crossfadeMs)) / crossfadeMs,
        EASE_IN
      );
  }

  if (opacity < 0.01) return null;

  // Compute zoom
  const clipProgress = clipElapsedMs / clipDurationMs;
  const [zoomStart, zoomEnd] = activeClip.zoomRange;
  const zoomScale = interpolate(
    clipProgress,
    [0, 1],
    [zoomStart, zoomEnd],
    { easing: EASE_OUT }
  );

  // Loop the source video within the clip duration
  const srcDurationSec = Math.ceil(clipDurationMs / 1000);
  const srcTotalFrames = Math.round(srcDurationSec * fps);

  return (
    <AbsoluteFill style={{ zIndex: 3, opacity }}>
      <Sequence from={0} durationInFrames={srcTotalFrames}>
        <AbsoluteFill
          style={{
            transform: `scale(${zoomScale.toFixed(3)})`,
          }}
        >
          <Video
            src={staticFile(activeClip.file)}
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
              position: "absolute",
              top: "50%",
              left: "50%",
              transform: "translate(-50%, -50%)",
            }}
          />
        </AbsoluteFill>
      </Sequence>

      {debug && (
        <div
          style={{
            position: "absolute",
            top: 10,
            left: 10,
            color: "white",
            background: "rgba(0,0,0,0.7)",
            padding: "4px 8px",
            fontSize: 12,
            fontFamily: "monospace",
            zIndex: 10,
          }}
        >
          B-roll: {activeClip.file.split("/").pop() ?? "?"} | frame {frame} |
          opacity {(opacity * 100).toFixed(0)}%
        </div>
      )}
    </AbsoluteFill>
  );
};

export default BrollLayer;
